// Shared by the server-rendering test, the hydration test and the script that renders
// the pages for hydration in a separate process. Plain erasable TypeScript: Node runs it as is.
import '@angular/compiler';
import { Component, inject, PendingTasks, type Type } from '@angular/core';
import { FormControl, FormsModule, ReactiveFormsModule } from '@angular/forms';
import * as hawiyah from '@hawiyah/angular';

/** Every exported class that Angular can place in a template, keyed by export name. */
export const declarations = Object.entries(hawiyah).flatMap(([name, value]) => {
  const type = value as unknown as { ɵcmp?: { selectors: unknown[][] }; ɵdir?: { selectors: unknown[][] } };
  if (typeof value !== 'function') return [];
  const definition = type.ɵcmp ?? type.ɵdir;
  return definition?.selectors.length ? [{ name, type: value as unknown as Type<object> }] : [];
});
export const valueControls = declarations.filter(({ type }) => typeof type.prototype.writeValue === 'function').map(({ name }) => name);

const cities = [{ value: 'riyadh', label: 'Riyadh' }, { value: 'jeddah', label: 'Jeddah' }, { value: 'dammam', label: 'Dammam', disabled: true }];
const links = [{ label: 'Home', href: 'https://example.org/', current: true }, { label: 'Services', href: 'https://example.org/services' }];
/** Hawiyah ships no strings, so each page supplies its own text. Templated text is a function
 * of the application; every host exposes these as `text`. */
export const text = {
  results: (count: number) => `${count} results`,
  selected: (count: number) => `${count} selected`,
  files: (files: readonly { name: string }[]) => `${files.length} files selected`,
  rejected: (files: readonly { name: string }[]) => `${files.length} files were not accepted`,
  format: (value: number) => `${value} percent`,
  range: (lower: number, upper: number) => `${lower} to ${upper}`,
  rating: (value: number, max: number) => `${value} of ${max}`,
  remove: (tag: string) => `Remove ${tag}`,
  overflow: (count: number) => `${count} more people`,
  slide: (position: number, total: number) => `Slide ${position} of ${total}`,
  page: (page: number) => `Page ${page}`,
  expand: (node: { label: string }) => `Expand ${node.label}`,
  collapse: (node: { label: string }) => `Collapse ${node.label}`,
  gap: (start: number, end: number) => `Pages ${start} to ${end}`,
  dismissToast: (toast: { message: string }) => `Dismiss: ${toast.message}`,
  dismissNotification: (item: { title: string }) => `Dismiss: ${item.title}`,
  markRead: (item: { title: string }) => `Mark as read: ${item.title}`,
  uploads: { selected: 'Selected', uploading: 'Uploading', complete: 'Uploaded', error: 'Failed', remove: 'Remove', getProgressLabel: (name: string) => `Uploading ${name}`, getRemoveLabel: (name: string) => `Remove ${name}` },
};

